sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  c.formData = {
    name: "",
    application_type: "",
    client: "",
    business_unit: "",
    criticality: "",
    integration_type: "",
    due_date: "",
    template_id: ""
  };

  c.saving = false;
  c.successMessage = "";
  c.errorMessage = "";

  c.applicationTypes = [
    { value: "saas", label: "SaaS" },
    { value: "on_premise", label: "On-Premise" },
    { value: "hybrid", label: "Hybrid" },
    { value: "custom", label: "Custom" },
    { value: "cots", label: "COTS" }
  ];

  c.businessUnits = [
    { value: "finance", label: "Finance" },
    { value: "hr", label: "Human Resources" },
    { value: "it", label: "Information Technology" },
    { value: "operations", label: "Operations" },
    { value: "sales", label: "Sales" },
    { value: "legal", label: "Legal" },
    { value: "engineering", label: "Engineering" }
  ];

  c.criticalityLevels = [
    { value: "critical", label: "Critical" },
    { value: "high", label: "High" },
    { value: "medium", label: "Medium" },
    { value: "low", label: "Low" }
  ];

  c.integrationTypes = [
    { value: "saml", label: "SAML" },
    { value: "oauth", label: "OAuth" },
    { value: "ldap", label: "LDAP" },
    { value: "radius", label: "RADIUS" },
    { value: "kerberos", label: "Kerberos" },
    { value: "custom", label: "Custom" },
    { value: "none", label: "None" }
  ];

  c.saveApplication = function() {
    if (!c.formData.name) {
      c.errorMessage = "Application Name is required.";
      return;
    }

    c.saving = true;
    c.errorMessage = "";
    c.successMessage = "";

    c.server.get({
      action: "create",
      name: c.formData.name,
      application_type: c.formData.application_type,
      client: c.formData.client,
      business_unit: c.formData.business_unit,
      criticality: c.formData.criticality,
      integration_type: c.formData.integration_type,
      due_date: c.formData.due_date,
      template_id: c.formData.template_id
    }).then(function(r) {
      c.saving = false;
      if (r.data.createdAppId) {
        c.successMessage = r.data.message;
        $scope.$emit("application.created", { app_id: r.data.createdAppId });
      } else {
        c.errorMessage = r.data.message || "Failed to create application.";
      }
    }, function() {
      c.saving = false;
      c.errorMessage = "An error occurred. Please try again.";
    });
  };

  c.resetForm = function() {
    c.formData = {
      name: "",
      application_type: "",
      client: "",
      business_unit: "",
      criticality: "",
      integration_type: "",
      due_date: "",
      template_id: ""
    };
    c.successMessage = "";
    c.errorMessage = "";
  };
};

sp_widget.css:
.ibar-create-form {
  padding: 20px;
}
.ibar-create-form .section-title {
  margin-bottom: 24px;
  font-size: 20px;
  font-weight: 600;
  color: #333;
  border-bottom: 2px solid #0078d4;
  padding-bottom: 10px;
}
.ibar-create-form .form-group {
  margin-bottom: 16px;
}
.ibar-create-form .control-label {
  font-weight: 500;
  margin-bottom: 6px;
  display: block;
}
.ibar-create-form .form-actions {
  margin-top: 24px;
  padding-top: 16px;
  border-top: 1px solid #e0e0e0;
}
.ibar-create-form .form-actions .btn {
  margin-right: 10px;
}
.ibar-create-form .help-block {
  font-size: 12px;
  color: #666;
}

sp_widget.script:
(function() {
  data.clients = [];
  data.templates = [];
  data.message = "";
  data.createdAppId = "";

  try {
    if (input && input.action === "create") {
      createApplication(input);
      return;
    }

    loadClients();
    loadTemplates();
  } catch (e) {
    gs.error("IBAR Application Create Form error: " + e.message);
    data.message = "An error occurred loading form data.";
  }

  function loadClients() {
    var gr = new GlideRecord("core_company");
    gr.addActiveQuery();
    gr.orderBy("name");
    gr.setLimit(100);
    gr.query();
    while (gr.next()) {
      data.clients.push({
        sys_id: gr.getUniqueValue(),
        name: gr.getValue("name")
      });
    }
  }

  function loadTemplates() {
    var gr = new GlideRecord("x_1433041_identi_0_questionnaire_template");
    gr.addQuery("active", true);
    gr.addQuery("status", "published");
    gr.orderBy("name");
    gr.query();
    while (gr.next()) {
      data.templates.push({
        sys_id: gr.getUniqueValue(),
        name: gr.getValue("name"),
        version: gr.getValue("version"),
        is_default: gr.getValue("is_default") == "true"
      });
    }
  }

  function createApplication(params) {
    var gr = new GlideRecord("x_1433041_identi_0_application");
    gr.initialize();
    gr.setValue("name", params.name || "");
    gr.setValue("application_type", params.application_type || "");
    gr.setValue("client", params.client || "");
    gr.setValue("business_unit", params.business_unit || "");
    gr.setValue("criticality", params.criticality || "");
    gr.setValue("integration_type", params.integration_type || "");
    gr.setValue("due_date", params.due_date || "");
    gr.setValue("questionnaire_status", "draft");
    gr.setValue("active", true);

    if (params.template_id) {
      gr.setValue("questionnaire_template", params.template_id);
      var tplGr = new GlideRecord("x_1433041_identi_0_questionnaire_template");
      if (tplGr.get(params.template_id)) {
        gr.setValue("questionnaire_version", tplGr.getValue("version"));
      }
    }

    var appId = gr.insert();
    if (appId) {
      data.createdAppId = appId;
      data.message = "Application created successfully.";

      var auditGr = new GlideRecord("x_1433041_identi_0_audit_event");
      auditGr.initialize();
      auditGr.setValue("application", appId);
      auditGr.setValue("event_type", "application_created");
      auditGr.setValue("description", "Application created: " + params.name);
      auditGr.setValue("performed_by", gs.getUserID());
      auditGr.setValue("performed_at", new GlideDateTime().getDisplayValue());
      auditGr.setValue("target_table", "x_1433041_identi_0_application");
      auditGr.setValue("target_record", appId);
      auditGr.insert();
    } else {
      data.message = "Failed to create application.";
    }
  }
})();
